{
  "scene_summary": {
    "text": "陶侃从上游赶来赴苏峻之难，提出要杀庾亮，认为杀掉庾亮可以安抚苏峻。庾亮进退两难：想逃又不可以，想见又怕被捉。温公劝庾亮去见陶侃，说只需遥拜即可，并愿为他担保。庾亮依言前往，到后便拜；陶侃起身制止，问他为何拜自己；庾亮又退到下一等座位，陶侃又邀他同坐。坐定后，庾亮引咎自责、深相逊谢，陶侃不觉释然。",
    "evidence_refs": ["evidence-sc1-27-jiajue-008-main"]
  },
  "participant_states": [
    {
      "person_id": "person-010",
      "surface": "庾公/庾亮",
      "state": "进退两难；最终接受温公建议，往见陶侃；见时即拜，并退居下坐，随后引咎责躬、深相逊谢。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-main"]
    },
    {
      "person_id": "person-064",
      "surface": "陶公/陶士衡/陶侃",
      "state": "自上流来赴苏峻之难，初令杀庾亮；见庾亮拜己，起而阻止，连请同坐；在庾亮道歉后不觉释然。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-main"]
    },
    {
      "person_id": null,
      "surface": "温公",
      "state": "劝庾亮前往见陶，并承诺‘但遥拜必无它’，为其担保。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-main"]
    }
  ],
  "relationship_context": [
    {
      "text": "陶侃起初要求杀庾亮以谢苏峻，但在庾亮拜见、退坐、引咎自责后，不觉释然，对立关系化解。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-main"]
    },
    {
      "text": "温公在庾亮与陶侃之间充当劝说者和担保者，促成这次会面。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-main"]
    }
  ],
  "reader_needed_context": [
    {
      "text": "背景：成帝年幼，太后临朝，庾亮以元舅辅政。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-annotation-001"]
    },
    {
      "text": "苏峻拥兵近甸，庾亮图召苏峻；苏峻认为庾亮要诱杀自己，遂怒而反，攻陷京邑。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-annotation-002", "evidence-sc1-27-jiajue-008-annotation-003"]
    },
    {
      "text": "庾亮败绩后投奔温峤，温峤敬重他并分兵配给；王愆期推陶侃为盟主，同赴京师。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-annotation-004"]
    },
    {
      "text": "程炎震注认为此事发生在咸和三年，即庾亮奔寻阳时。",
      "evidence_refs": ["s1-assertion-8d9bfa662b350908073b"]
    }
  ],
  "uncertainties": [
    {
      "text": "正文中的‘温公’未在资料包中被显式解析为温嶠；温嶠仅出现在注文背景中。场景中暂以‘温公’原表面名呈现，不做身份对应。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-main", "evidence-sc1-27-jiajue-008-annotation-003"]
    },
    {
      "text": "正文只以‘苏峻之难’为宽泛时间背景；程炎震注给出咸和三年（亮奔寻阳时），但该年份并非正文明文。",
      "evidence_refs": ["evidence-sc1-27-jiajue-008-main", "s1-assertion-8d9bfa662b350908073b"]
    }
  ]
}
